  List<int> result = [];

  int level = 0;

  for (int i = 0; i < parenString.length; i++) {
    if (parenString[i] == '(') {
      level++;
    } else if (parenString[i] == ')') {
      level--;

      while (level != 1 && i + 1 < parenString.length 
              && parenString[i+1] == ')' 
              && parenString[i-2] == '(') {
        i += 3; // Skip over "())" pattern
        result.add(level - 1);

        if (i >= parenString.length) break;

        if (parenString[i] == '(') {
          level -= 2;
        }
      }

      result.add(level);

      if (level > 0) {
        level--;
      }
    }
  }


  return result;
}

