double triangleArea(double a, double b, double c) {
  if (a + b <= c || a + c <= b || b + c <= a) {
    return -1;
  }
  double s = (a + b + c) / 2;
  double area = sqrt(s * (s - a) * (s - b) * (s - c));
  area = (area * 100).roundToDouble() / 100;
  return area;
}

