  if (array.length <= 1) return array;


  int pivot = array[array.length ~/ 2];


  List<int> smallerOrEqual = [];
  List<int> greaterThanPivot = [];

  for (int num in array) {
    if (num <= pivot) {
      smallerOrEqual.add(num);
    } else {
      greaterThanPivot.add(num);
    }
  }


  List<int> sortedLeft = sortArray(smallerOrEqual);
  List<int> sortedRight = sortArray(greaterThanPivot);


  return [...sortedLeft, pivot, ...sortedRight];
}

