int multiply(int a, int b) {
  if (a == 0 || b == 0) return 0; 
  bool neg = false;


  if ((a < 0 && b > 0) || (b < 0 && a > 0)) {
    neg = true;
    a = -a;
    b = -b;
  } 

  int res = 0;


  while (a != 0) {
    if (a & 1 == 1) res += b; 
    b <<= 1;    
    a >>= 1;     
  }

  return neg ? -res : res;
}

