int closestInteger(String value) {
  String processedValue = value;

  if (value.contains('.')) {
    while (processedValue.endsWith('0') && processedValue.contains('.')) {
      processedValue = processedValue.substring(0, processedValue.length - 1);
    }
  }

  double num = double.parse(processedValue);
  int res;

  if (processedValue.length >= 2 && processedValue.substring(processedValue.length - 2) == '.5') {
    if (num > 0) {
      res = num.ceil();
    } else {
      res = num.floor();
    }
  } else if (processedValue.isNotEmpty) {
    res = num.round();
  } else {
