int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;

  List<bool> visited = List.filled(rows * cols, false);
  Map<String, bool> memo = {};
  int filledCount = 0;

  void dfs(int rowIdx, int colIdx) {
    final key = '${rowIdx}-${colIdx}';

    // Check if we've already visited this cell or it's out of bounds
    if (visited[rowIdx * cols + colIdx] || 
        rowIdx < 0 || rowIdx >= rows || 
        colIdx < 0 || colIdx >= cols) {
      return;
    }

    // If the cell is full (value = 1), mark as visited and continue DFS
    if (grid[rowIdx][colIdx] == 1) {
      visited[rowIdx * cols + colIdx] = true;

      // Add to total count if not yet added
      if (!memo.containsKey(key)) {
        filledCount++;
        memo[key] = true;

        // Continue DFS in all four directions
        dfs(rowIdx - 1, colIdx);
        dfs(rowIdx + 1, colIdx);
        dfs(rowIdx, colIdx - 1);
        dfs(rowIdx, colIdx + 1);
      }
    }
  }

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (grid[i][j] == 0 && !visited[i * cols + j]) {
        dfs(i, j);
      }
    }
  }

  return filledCount;
}

