String matchParens(List<String> lst) {
  int stackCount = 0;

  for (final str in lst) {
    final List<int> charCodes = str.codeUnits;

    for (int i = 0; i < charCodes.length; i++) {
      if (charCodes[i] == '(' || charCodes[i] == '[' || charCodes[i] == '{') {
        stackCount++;
      } else if (charCodes[i] == ')' || charCodes[i] == ']' || charCodes[i] == '}') {
        stackCount--;

        // If the count goes negative, there's an unmatched closing bracket.
        if (stackCount < 0) {
          return "No";
        }
      }
    }
  }

  return stackCount == 0 ? "Yes" : "No";
}

