  List<int> openingBracketIndex = [];
  List<int> closingBracketIndex = [];

  for (int i = 0; i < string.length; i++) {
    if (string[i] == '[') {
      openingBracketIndex.add(i);
    } else {
      closingBracketIndex.add(i);
    }
