  print(doAlgebra(['*', '+'], [2, 3, 4])); // Expected: 10

  // Test case 3: 10 - 5 = 5
  print(doAlgebra(['-'], [10, 5])); // Expected: 5

  // Test case 4: 2 ** 3 = 8
  print(doAlgebra(['**'], [2, 3])); // Expected: 8

  // Test case 5: 10 // 3 = 3
  print(doAlgebra(['//'], [10, 3])); // Expected: 3

  // Test case 6: 2 ** 3 * 4 = 32
